SELECT 1
FROM med_schedule
WHERE doctor_id = #{doctorId}
  AND work_date = #{workDate,jdbcType=DATE}
  AND active_flag = 1
  AND start_time < #{endTime,jdbcType=TIME}
  AND end_time > #{startTime,jdbcType=TIME}
LIMIT 1

SELECT 1
FROM med_schedule
WHERE clinic_room_id = #{clinicRoomId}
  AND work_date = #{workDate,jdbcType=DATE}
  AND active_flag = 1
  AND start_time < #{endTime,jdbcType=TIME}
  AND end_time > #{startTime,jdbcType=TIME}
LIMIT 1

mapper.update:
UPDATE med_schedule
SET status = #{publishedStatus}
WHERE id = #{scheduleId}
  AND status = #{draftStatus}
